import{z as l,x as i,o as E,c as d,q as s,j as B,D as n,d as r,s as A,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"地址映射与交织","description":"","frontmatter":{"title":"地址映射与交织","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/address-interleaving.md","filePath":"cs/address-interleaving.md","lastUpdated":1791063341000}'),D={name:"cs/address-interleaving.md"};function p(C,a,b,c,k,m){const t=i("Mermaid");return E(),d("div",null,[a[2]||(a[2]=s('<h1 id="地址映射与交织" tabindex="-1">地址映射与交织 <a class="header-anchor" href="#地址映射与交织" aria-label="Permalink to &quot;地址映射与交织&quot;">​</a></h1><div class="epigraph"><p>物理地址哪几位当通道、哪几位当 bank、哪几位当行，决定连续 cache 行是打在同一行缓冲里还是洒开并行——这是控制器的译码，不是 ISA 的一部分。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；JEDEC DDR 组织；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/ddr-protocol">上一课</a>能发合法命令了。物理地址还是扁平的。<a href="/cs/dram-organization">DRAM 组织</a>留下「哪些位选哪一层」。缺口是 <strong>地址映射</strong>：交织（interleaving）如何权衡行命中与 bank/通道并行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>cache 行对齐的连续地址：若低位先切列与 bank，相邻行走不同 bank（bank 交织），冲突少、打开页命中也可能少。若低位先切列且同行，空间局部性吃行缓冲，顺序流式好，随机跨行则冲突堆在同一 bank。通道交织把连续块洒到多通道以拉带宽。缺口不是新的 DDR 命令，而是这张<strong>位切片表</strong>是微结构合同，OS 看到的仍是物理页。</p><p>XOR 银行哈希减轻步长冲突（如每 256 字节一冲突的列步长）。本课点名，不证哈希最优。</p><h3 id="映射不是「虚拟内存页表」" tabindex="-1">映射不是「虚拟内存页表」 <a class="header-anchor" href="#映射不是「虚拟内存页表」" aria-label="Permalink to &quot;映射不是「虚拟内存页表」&quot;">​</a></h3><p>页表把 VA→PA；PA 再被内存控制器切成 DRAM 坐标。程序员与 OS 通常不能直接选 bank。把 bank 当成另一种页大小，缺页处理会写错。大页只改变 VA 映射粒度，不自动改变通道交织。</p><p><span class="marginnote">CA:AQA 讨论交错与并行。控制器手册（厂商）给具体位场，本课用教学切片。JEDEC 不规定 CPU 如何把 PA 切到位，只规定颗粒看见的行/列。</span></p><p><span class="marginnote">直觉类比：把内存想成一栋楼——通道是并排的几栋楼，bank 是楼里的电梯，行是电梯停靠的整层。连续访存分进不同电梯（bank 交织）可以同时上下；全挤同一层时开一次门搬走一整层（行缓冲命中）也很快。位切片表决定你吃到哪种红利。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型：<code>PA = [通道 | rank | 行 | bank | 列 | 字节]</code> 或把 bank/通道放到更低位。cache 行大小应对齐突发。NUMA：高位先选节点，再进本地通道映射。HBM 伪通道是另一套低位切片。</p>',12)),(E(),B(o,null,{default:n(()=>[A(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PA%5B%22%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20MAP%5B%22%E4%BD%8D%E5%88%87%E7%89%87%20%2F%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20MAP%20--%3E%20CH%5B%22%E9%80%9A%E9%81%93%E4%BA%A4%E7%BB%87%22%5D%0A%20%20MAP%20--%3E%20BK%5B%22bank%20%E4%BA%A4%E7%BB%87%22%5D%0A%20%20MAP%20--%3E%20ROW%5B%22%E8%A1%8C%E7%B4%A2%E5%BC%95%22%5D%0A%20%20ROW%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B0%83%E5%BA%A6%E5%99%A8%E7%9C%8B%E7%9D%80%E8%BF%99%E4%BA%9B%E5%9D%90%E6%A0%87%E6%8E%92%E9%98%9F%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"软件：伪随机访问对任何静态映射都可能最坏；结构感知的分配（靠近、对齐）是性能层，不是协议层。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"FR-FCFS 在给定映射下最大化行命中。换映射等于换调度器看到的冲突图。后课 HBM 把「通道」变宽，映射思想不变。持久内存会把同一 PA 切到另一介质，映射仍先发生。",-1)),a[6]||(a[6]=e("p",null,"第一张图画的是一个地址怎么被切成 DRAM 坐标；这张图回答第二个问题：同一串连续 cache 行，低位切法不同，落在硬件里的样子完全不同——这就是交织的权衡本身。",-1)),(E(),B(o,null,{default:n(()=>[A(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E8%BF%9E%E7%BB%AD%204%20%E6%9D%A1%20cache%20%E8%A1%8C%22%5D%20--%3E%20LOWBK%5B%22%E4%BD%8E%E4%BD%8D%E5%88%87%20bank%22%5D%0A%20%20LOWBK%20--%3E%20B0%5B%22%E8%A1%8C%200%20%E8%BF%9B%20bank%200%22%5D%0A%20%20LOWBK%20--%3E%20B1%5B%22%E8%A1%8C%201%20%E8%BF%9B%20bank%201%22%5D%0A%20%20LOWBK%20--%3E%20B2%5B%22%E8%A1%8C%202%20%E8%BF%9B%20bank%202%22%5D%0A%20%20LOWBK%20--%3E%20B3%5B%22%E8%A1%8C%203%20%E8%BF%9B%20bank%203%22%5D%0A%20%20B0%20--%3E%20PAR%5B%22%E5%9B%9B%E8%B7%AF%E5%B9%B6%E8%A1%8C%EF%BC%8C%E5%B8%A6%E5%AE%BD%E4%BC%98%E5%85%88%22%5D%0A%20%20B1%20--%3E%20PAR%0A%20%20SEQ%20--%3E%20LOWROW%5B%22%E4%BD%8E%E4%BD%8D%E5%88%87%E5%88%97%EF%BC%8C%E7%95%99%E5%9C%A8%E5%90%8C%E8%A1%8C%22%5D%0A%20%20LOWROW%20--%3E%20SAME%5B%22%E5%9B%9B%E6%9D%A1%E5%85%A8%E8%90%BD%E5%90%8C%E4%B8%80%E6%89%93%E5%BC%80%E8%A1%8C%22%5D%0A%20%20SAME%20--%3E%20HIT%5B%22%E8%A1%8C%E7%BC%93%E5%86%B2%E5%91%BD%E4%B8%AD%EF%BC%8C%E5%BB%B6%E8%BF%9F%E4%BC%98%E5%85%88%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">数字实例：若每个 256 字节落进同一通道，循环步长恰好 256 字节时永远只有一个通道干活，可用带宽只剩几分之一；XOR 银行哈希把地址位搅在一起，就是为了让这种「步长撞车」摊到各个 bank 上。</span></p><p><span class="marginnote">常见误区：初学者容易把 DRAM 的 bank、行坐标当成页表的一部分。页表只管虚拟地址到物理地址；物理地址再切成通道、bank、行、列是内存控制器定死的微结构合同，操作系统与程序员通常都插不上手。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某 Intel/AMD 代际的真实位场，不写 RowHammer 地址邻近的完整模型。不把 GPU 显存 tiling 当 DDR 映射定义。</p><p>后课默认：PA 到通道/rank/bank/行/列由控制器映射；交织权衡命中与并行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>页表之后还有 DRAM 坐标译码。</li><li>低位切 bank/通道 → 并行；低位留同行 → 页模式命中。</li><li>调度器吃的是映射后的坐标。</li><li>出处：Hennessy and Patterson, CA:AQA；JEDEC 组织；Patterson and Hennessy, COD。</li></ul>',7))])}const u=l(D,[["render",p]]);export{P as __pageData,u as default};
